import{_ as e,o as i,c as l,a5 as t}from"./chunks/framework.CXroN2RO.js";const g=JSON.parse('{"title":"発展編 専門テーマを選ぶ","description":"","frontmatter":{"title":"発展編 専門テーマを選ぶ","study":{"source":"IT教本","status":"outline","summary":"本編から先に調べる専門テーマと、そのための教材・演習を選ぶ学習計画・概要です。すべてを必修にせず、実装したいものや観測した問題に合わせて選びます。Rust、Linuxカーネル、ゲーム通信、オーディオなどの専用本文は未整備です。\\n\\n## 関連する辞典本文・実践\\n\\n- [並行処理のバグ](/ru","section":"learning","format":"path","domain":"game","collection":"low-level","order":21}},"headers":[],"relativePath":"guide/low-level/advanced-topics.md","filePath":"guide/low-level/advanced-topics.md"}'),r={name:"guide/low-level/advanced-topics.md"};function o(n,a,s,d,u,h){return i(),l("div",null,[...a[0]||(a[0]=[t('<div id="発展編-──-普通のゲームプログラマは学ばなくてよいが、トップを目指すなら価値が高いトピック" class="study-legacy-anchor" aria-hidden="true"></div><h1 id="発展編-専門テーマを選ぶ" tabindex="-1">発展編 専門テーマを選ぶ <a class="header-anchor" href="#発展編-専門テーマを選ぶ" aria-label="Permalink to &quot;発展編 専門テーマを選ぶ&quot;">​</a></h1><h2 id="このページで案内すること" tabindex="-1">このページで案内すること <a class="header-anchor" href="#このページで案内すること" aria-label="Permalink to &quot;このページで案内すること&quot;">​</a></h2><p>本編から先に調べる専門テーマと、そのための教材・演習を選ぶ<strong>学習計画・概要</strong>です。すべてを必修にせず、実装したいものや観測した問題に合わせて選びます。Rust、Linuxカーネル、ゲーム通信、オーディオなどの専用本文は未整備です。</p><h2 id="関連する辞典本文・実践" tabindex="-1">関連する辞典本文・実践 <a class="header-anchor" href="#関連する辞典本文・実践" aria-label="Permalink to &quot;関連する辞典本文・実践&quot;">​</a></h2><ul><li><a href="/study/runtime/memory/concurrency-bugs.html">並行処理のバグ</a>、<a href="/study/graphics/compute/compute-shader.html">Compute Shader</a>で、並行・並列処理を調べられます。</li><li><a href="/study/graphics/lighting/raytracing.html">レイトレーシング</a>と<a href="/study/game/unreal/build-system-ubt.html">UBT・Module</a>は、描画とビルドの専門テーマへ進む入口です。</li></ul><p>本編(第0〜19章)では、ゲームを支える主要な層の関係を学ぶ。 ここから先は、担当する機能や関心に合わせて深掘りする専門テーマである。 すべてやる必要はない。<strong>自分の目指す専門性に合わせて2〜3本選ぶ</strong>こと。 各トピックに「誰が学ぶべきか」を明記した。</p><hr><h2 id="a-cpu・低レイヤ系" tabindex="-1">A. CPU・低レイヤ系 <a class="header-anchor" href="#a-cpu・低レイヤ系" aria-label="Permalink to &quot;A. CPU・低レイヤ系&quot;">​</a></h2><h3 id="a-1-simd-sse-avx-neon" tabindex="-1">A-1. SIMD(SSE/AVX/NEON) <a class="header-anchor" href="#a-1-simd-sse-avx-neon" aria-label="Permalink to &quot;A-1. SIMD(SSE/AVX/NEON)&quot;">​</a></h3><ul><li><strong>誰向け</strong>: 物理・アニメ・オーディオ・数学ライブラリを書く人</li><li>1命令で4〜16個のfloatを処理。DirectXMath/Burstの中身。 イントリンシクス(<code>_mm_mul_ps</code>)、シャッフル、水平演算、 AoS→SoA変換(第3章の本当の動機)</li><li>教材: Intel Intrinsics Guide、Agner Fogの最適化マニュアル、 DirectXMathのソース</li><li>演習: 自作Vec4/行列乗算をSSEで書き、スカラ版と計測比較</li></ul><h3 id="a-2-cpuマイクロアーキテクチャ深掘り" tabindex="-1">A-2. CPUマイクロアーキテクチャ深掘り <a class="header-anchor" href="#a-2-cpuマイクロアーキテクチャ深掘り" aria-label="Permalink to &quot;A-2. CPUマイクロアーキテクチャ深掘り&quot;">​</a></h3><ul><li><strong>誰向け</strong>: エンジン最適化の最終責任者になりたい人</li><li>パイプライン段数、スーパースカラ、アウトオブオーダー、 リオーダバッファ、分岐予測器の実装、投機実行、 ポート競合、μop、Spectre/Meltdownの原理</li><li>教材: Agner Fog &quot;The microarchitecture of Intel, AMD and VIA CPUs&quot;、 『プロセッサを支える技術』、uops.info</li><li>演習: VTune/uProfでIPC・分岐ミス率・ポート使用率を読む</li></ul><h3 id="a-3-ロックフリープログラミングとメモリモデル" tabindex="-1">A-3. ロックフリープログラミングとメモリモデル <a class="header-anchor" href="#a-3-ロックフリープログラミングとメモリモデル" aria-label="Permalink to &quot;A-3. ロックフリープログラミングとメモリモデル&quot;">​</a></h3><ul><li><strong>誰向け</strong>: ジョブシステム・オーディオエンジンを書く人</li><li>C++メモリモデル(acquire/release/seq_cst)、CAS、ABA問題、 SPSC/MPMCキュー、ヘイズポインタ</li><li>教材: 『C++ Concurrency in Action』、Preshing on Programmingブログ</li><li>演習: SPSCリングバッファを書き、TSanで検証(オーディオスレッドへの コマンド送信は実務でそのまま使う)</li></ul><h2 id="b-コンパイラ・言語系" tabindex="-1">B. コンパイラ・言語系 <a class="header-anchor" href="#b-コンパイラ・言語系" aria-label="Permalink to &quot;B. コンパイラ・言語系&quot;">​</a></h2><h3 id="b-4-llvm" tabindex="-1">B-4. LLVM <a class="header-anchor" href="#b-4-llvm" aria-label="Permalink to &quot;B-4. LLVM&quot;">​</a></h3><ul><li><strong>誰向け</strong>: シェーダコンパイラ・スクリプト処理系・ツールチェーン担当</li><li>IR、パス、バックエンド。Clang/DXC/Burst/IL2CPPの土台。 「自作言語→LLVM IR→ネイティブ」の体験は視界を変える</li><li>教材: 公式Kaleidoscopeチュートリアル、『きつねさんでもわかるLLVM』</li><li>演習: Kaleidoscope完走。自作ミニ言語をJIT実行</li></ul><h3 id="b-5-jitとvm・gc実装" tabindex="-1">B-5. JITとVM・GC実装 <a class="header-anchor" href="#b-5-jitとvm・gc実装" aria-label="Permalink to &quot;B-5. JITとVM・GC実装&quot;">​</a></h3><ul><li><strong>誰向け</strong>: スクリプト組み込み(Lua)・Mod対応・処理系好き</li><li>バイトコードVM(スタック/レジスタ型)、インラインキャッシュ、 トレーシングJIT。GCアルゴリズム(世代別・インクリメンタル・ ムービング)── Unity/UEのGC(16,17章)の一般理論</li><li>教材: 『Crafting Interpreters』(無料Web・傑作)、LuaJITソース、 『ガベージコレクション』(中村成洋ら)</li><li>演習: Crafting Interpretersのclox(バイトコードVM+GC)完走 → 自作エンジンにLuaを組み込む</li></ul><h3 id="b-6-rust" tabindex="-1">B-6. Rust <a class="header-anchor" href="#b-6-rust" aria-label="Permalink to &quot;B-6. Rust&quot;">​</a></h3><ul><li><strong>誰向け</strong>: 次世代エンジン・ツール開発、所有権思考を極めたい人</li><li>所有権・借用・ライフタイム=第6,9章の「所有権規約」を型システムで 強制したもの。ゲームでは Bevy、各社ツール系で採用増</li><li>教材: The Rust Book(公式・和訳あり)、Bevyソース</li><li>演習: 第15章のミニECSをRustで書き直す(borrow checkerとの戦いが 最高の所有権訓練)</li></ul><h2 id="c-os・インフラ系" tabindex="-1">C. OS・インフラ系 <a class="header-anchor" href="#c-os・インフラ系" aria-label="Permalink to &quot;C. OS・インフラ系&quot;">​</a></h2><h3 id="c-7-linuxカーネル読解-os自作完走" tabindex="-1">C-7. Linuxカーネル読解 / OS自作完走 <a class="header-anchor" href="#c-7-linuxカーネル読解-os自作完走" aria-label="Permalink to &quot;C-7. Linuxカーネル読解 / OS自作完走&quot;">​</a></h3><ul><li><strong>誰向け</strong>: サーバ・コンソールプラットフォーム担当、低レイヤ極道</li><li>スケジューラ(CFS/EEVDF)、メモリ管理(buddy/slab)、io_uring。 または『ゼロからのOS自作入門』完走</li><li>教材: 『詳解Linuxカーネル』、カーネルソース、MikanOS</li><li>演習: straceとftraceで自作ゲームのシステムコールを全部説明する</li></ul><h3 id="c-8-コンソール開発の流儀-学べる範囲で" tabindex="-1">C-8. コンソール開発の流儀(学べる範囲で) <a class="header-anchor" href="#c-8-コンソール開発の流儀-学べる範囲で" aria-label="Permalink to &quot;C-8. コンソール開発の流儀(学べる範囲で)&quot;">​</a></h3><ul><li><strong>誰向け</strong>: 家庭用タイトルの最適化担当を目指す人</li><li>固定ハードの強み: 統合メモリ、明示的なコア割り当て、 プラットフォーム固有API、TRC/ロットチェック文化、認証要件</li><li>NDA外で学べるもの: GDC講演(各社ポストモーテム)、 統合メモリ=第11章、SPU時代の資料(データ指向の源流として今も価値)</li><li>演習: 「メモリ予算表」「フレーム予算表」を自作ゲームに作る (コンソール開発の文化を先取りする訓練)</li></ul><h2 id="d-グラフィックス発展系" tabindex="-1">D. グラフィックス発展系 <a class="header-anchor" href="#d-グラフィックス発展系" aria-label="Permalink to &quot;D. グラフィックス発展系&quot;">​</a></h2><h3 id="d-9-レイトレーシングとgi" tabindex="-1">D-9. レイトレーシングとGI <a class="header-anchor" href="#d-9-レイトレーシングとgi" aria-label="Permalink to &quot;D-9. レイトレーシングとGI&quot;">​</a></h3><ul><li><strong>誰向け</strong>: レンダリングエンジニア志望</li><li>BVH走査、DXR/Vulkan RT、デノイズ、パストレーシング理論、 Lumen/ReSTIRの論文群</li><li>教材: &quot;Ray Tracing in One Weekend&quot;(無料・まずこれ)、PBRT(聖典)</li><li>演習: One Weekend三部作→DXRで三角形1枚→自作エンジンにRT影</li></ul><h3 id="d-10-gpu駆動レンダリングとnanite的世界" tabindex="-1">D-10. GPU駆動レンダリングとNanite的世界 <a class="header-anchor" href="#d-10-gpu駆動レンダリングとnanite的世界" aria-label="Permalink to &quot;D-10. GPU駆動レンダリングとNanite的世界&quot;">​</a></h3><ul><li><strong>誰向け</strong>: 大規模シーン・次世代レンダラ担当</li><li>インダイレクトドロー、GPUカリング、メッシュレット、 バインドレス、Naniteの仕組み(SIGGRAPH講演)</li><li>教材: SIGGRAPH Advances in Real-Time Rendering、Naniteの &quot;A Deep Dive into Nanite&quot; 講演、vkguideのGPU-driven章</li><li>演習: コンピュートシェーダでフラスタムカリング→ ExecuteIndirectで10万オブジェクト描画</li></ul><h3 id="d-11-コンピュートシェーダとgpgpu" tabindex="-1">D-11. コンピュートシェーダとGPGPU <a class="header-anchor" href="#d-11-コンピュートシェーダとgpgpu" aria-label="Permalink to &quot;D-11. コンピュートシェーダとGPGPU&quot;">​</a></h3><ul><li><strong>誰向け</strong>: エフェクト・シミュレーション・AI推論をGPUでやる人</li><li>スレッドグループ、共有メモリ、リダクション、prefix sum、 パーティクル/流体/クロスシミュレーション</li><li>教材: CUDAプログラミングガイド(概念習得に最適)、 各種compute shaderチュートリアル</li><li>演習: GPUパーティクル100万個(更新も描画もGPU)</li></ul><h2 id="e-ゲームシステム発展系" tabindex="-1">E. ゲームシステム発展系 <a class="header-anchor" href="#e-ゲームシステム発展系" aria-label="Permalink to &quot;E. ゲームシステム発展系&quot;">​</a></h2><h3 id="e-12-物理エンジン自作" tabindex="-1">E-12. 物理エンジン自作 <a class="header-anchor" href="#e-12-物理エンジン自作" aria-label="Permalink to &quot;E-12. 物理エンジン自作&quot;">​</a></h3><ul><li><strong>誰向け</strong>: 物理・キャラクタ挙動の専門家志望</li><li>積分器(semi-implicit Euler)、broadphase(SAP/BVH)、 narrowphase(GJK/EPA)、拘束ソルバ(sequential impulse)、 スタッキングの安定化</li><li>教材: Box2Dソース+Erin Cattoの GDC講演群(全部公開)、 &quot;Game Physics Engine Development&quot;</li><li>演習: 2D剛体エンジン(円と箱、衝突応答、スタック)を自作 → Box2Dと比較読解</li></ul><h3 id="e-13-ネットワーク-マルチプレイヤー" tabindex="-1">E-13. ネットワーク(マルチプレイヤー) <a class="header-anchor" href="#e-13-ネットワーク-マルチプレイヤー" aria-label="Permalink to &quot;E-13. ネットワーク(マルチプレイヤー)&quot;">​</a></h3><ul><li><strong>誰向け</strong>: オンラインゲーム担当(現代ではほぼ必修に近い)</li><li>TCP/UDP、クライアントサーバ/P2P、予測と補間、ラグ補償、 スナップショット圧縮、<strong>決定性ロールバック</strong>(GGPO、第14章の延長)、 UEのレプリケーション内部</li><li>教材: Gaffer On Games(無料・必読)、&quot;Multiplayer Game Programming&quot;、 GGPO/Photon/UE Replicationソース</li><li>演習: UDPで2人対戦Pong(予測・補間・ロールバック付き)</li></ul><h3 id="e-14-オーディオプログラミング" tabindex="-1">E-14. オーディオプログラミング <a class="header-anchor" href="#e-14-オーディオプログラミング" aria-label="Permalink to &quot;E-14. オーディオプログラミング&quot;">​</a></h3><ul><li><strong>誰向け</strong>: サウンドプログラマ志望(希少価値が高い)</li><li>サンプリング定理、ミキシング、リングバッファとレイテンシ(第10章回収)、 DSP(フィルタ・リバーブ)、WASAPI/XAudio2、ミドルウェア(Wwise)の内部像</li><li>教材: &quot;The Audio Programming Book&quot;、miniaudioソース</li><li>演習: miniaudioで自作ミキサ(同時32音・ピッチ・3Dパン)</li></ul><h2 id="f-その他" tabindex="-1">F. その他 <a class="header-anchor" href="#f-その他" aria-label="Permalink to &quot;F. その他&quot;">​</a></h2><h3 id="f-15-ビルドインフラとdevops-for-games" tabindex="-1">F-15. ビルドインフラとDevOps for Games <a class="header-anchor" href="#f-15-ビルドインフラとdevops-for-games" aria-label="Permalink to &quot;F-15. ビルドインフラとDevOps for Games&quot;">​</a></h3><ul><li><strong>誰向け</strong>: テックリード・エンジンチーム</li><li>分散ビルド(IncrediBuild/FASTBuild)、CI/CD、アセットビルドファーム、 パッチ配信、クラッシュ収集基盤(Sentry/Backtrace)</li><li>演習: 自作エンジンにGitHub Actionsでビルド+テスト+ クラッシュダンプ収集を整備</li></ul><h3 id="f-16-セキュリティとアンチチート" tabindex="-1">F-16. セキュリティとアンチチート <a class="header-anchor" href="#f-16-セキュリティとアンチチート" aria-label="Permalink to &quot;F-16. セキュリティとアンチチート&quot;">​</a></h3><ul><li><strong>誰向け</strong>: オンラインゲーム・ライブサービス担当</li><li>メモリ改竄(Cheat Engineの原理=第6,8章)、パケット改竄、 サーバ権威設計、難読化とその限界</li><li>演習: 自作ゲームをCheat Engineで自分でチートし、 サーバ権威化で防ぐ(攻撃を知る者だけが守れる)</li></ul><hr><h2 id="選び方の指針" tabindex="-1">選び方の指針 <a class="header-anchor" href="#選び方の指針" aria-label="Permalink to &quot;選び方の指針&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目指す専門</th><th>推奨セット</th></tr></thead><tbody><tr><td>レンダリングエンジニア</td><td>D-9, D-10, D-11 (+A-1)</td></tr><tr><td>エンジン/コアテック</td><td>A-1, A-3, B-4 or B-5, E-12</td></tr><tr><td>ゲームプレイ/ネットワーク</td><td>E-13, B-5(スクリプト), F-16</td></tr><tr><td>最適化スペシャリスト</td><td>A-1, A-2, A-3, C-8</td></tr><tr><td>ツール/パイプライン</td><td>B-4, B-6, F-15</td></tr><tr><td>サウンド</td><td>E-14, A-1, A-3</td></tr></tbody></table><p><strong>共通の助言</strong>: 発展トピックは「本編の該当章に不安があるなら戻る」が 鉄則。基礎の複利が最も効く投資であることは、ここまで来たあなたなら もう体感しているはずだ。</p>',50)])])}const m=e(r,[["render",o]]);export{g as __pageData,m as default};
